CREATE TABLE IF NOT EXISTS `kuesioner_kategori` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `id_status` int(11) DEFAULT NULL,
  `nama` varchar(150) NOT NULL,
  `deskripsi` text NOT NULL,
  `label_pertanyaan` varchar(150) NOT NULL DEFAULT 'Variabel Demografi',
  `urutan` int(11) NOT NULL DEFAULT 0,
  `status` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `id_status` (`id_status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `kuesioner_pertanyaan` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `kategori_id` int(11) NOT NULL,
  `kode` varchar(50) NOT NULL,
  `pertanyaan` text NOT NULL,
  `tipe` varchar(20) NOT NULL DEFAULT 'radio',
  `kunci_jawaban` varchar(50) DEFAULT NULL,
  `wajib` tinyint(1) NOT NULL DEFAULT 1,
  `urutan` int(11) NOT NULL DEFAULT 0,
  `status` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `kode` (`kode`),
  KEY `kategori_id` (`kategori_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `kuesioner_opsi` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `pertanyaan_id` int(11) DEFAULT NULL,
  `label` varchar(255) NOT NULL,
  `nilai` varchar(255) NOT NULL,
  `skor` int(11) NOT NULL DEFAULT 0,
  `urutan` int(11) NOT NULL DEFAULT 0,
  `status` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `pertanyaan_id` (`pertanyaan_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

ALTER TABLE `kuesioner_kategori`
  ADD COLUMN IF NOT EXISTS `id_status` int(11) DEFAULT NULL AFTER `id`,
  ADD KEY IF NOT EXISTS `id_status` (`id_status`);

ALTER TABLE `kuesioner_opsi`
  ADD COLUMN IF NOT EXISTS `pertanyaan_id` int(11) DEFAULT NULL AFTER `id`,
  MODIFY `label` varchar(255) NOT NULL,
  MODIFY `nilai` varchar(255) NOT NULL,
  ADD KEY IF NOT EXISTS `pertanyaan_id` (`pertanyaan_id`);

ALTER TABLE `demografi`
  ADD COLUMN IF NOT EXISTS `jenis_responden` varchar(100) DEFAULT NULL AFTER `id_user`,
  ADD COLUMN IF NOT EXISTS `kode_responden` varchar(50) DEFAULT NULL AFTER `jenis_responden`,
  ADD COLUMN IF NOT EXISTS `no_responden` varchar(50) DEFAULT NULL AFTER `kode_responden`,
  ADD COLUMN IF NOT EXISTS `kelas` varchar(50) DEFAULT NULL AFTER `gender`,
  ADD COLUMN IF NOT EXISTS `pendidikan_ayah` varchar(100) DEFAULT NULL AFTER `kelas`,
  ADD COLUMN IF NOT EXISTS `pendidikan_ibu` varchar(100) DEFAULT NULL AFTER `pendidikan_ayah`,
  ADD COLUMN IF NOT EXISTS `pekerjaan_ayah` varchar(150) DEFAULT NULL AFTER `pendidikan_ibu`,
  ADD COLUMN IF NOT EXISTS `pekerjaan_ibu` varchar(150) DEFAULT NULL AFTER `pekerjaan_ayah`,
  ADD COLUMN IF NOT EXISTS `pernah_informasi_hiv` varchar(10) DEFAULT NULL AFTER `pekerjaan_ibu`,
  ADD COLUMN IF NOT EXISTS `sumber_informasi_hiv` varchar(255) DEFAULT NULL AFTER `pernah_informasi_hiv`,
  MODIFY `gender` varchar(100) NOT NULL,
  MODIFY `pekerjaan` varchar(150) NOT NULL,
  MODIFY `pendidikan` varchar(150) NOT NULL,
  MODIFY `pendapatan` varchar(100) NOT NULL,
  MODIFY `pengalaman` varchar(150) NOT NULL;

ALTER TABLE `jawaban_kuesioner`
  MODIFY `pertanyaan` varchar(50) NOT NULL,
  MODIFY `jawaban` text NOT NULL;

ALTER TABLE `kuesioner_pertanyaan`
  ADD COLUMN IF NOT EXISTS `kunci_jawaban` varchar(50) DEFAULT NULL AFTER `tipe`;

DELETE FROM `kuesioner_opsi`;
DELETE FROM `kuesioner_pertanyaan`;
DELETE FROM `kuesioner_kategori`;
ALTER TABLE `kuesioner_kategori` AUTO_INCREMENT = 1;
ALTER TABLE `kuesioner_pertanyaan` AUTO_INCREMENT = 1;
ALTER TABLE `kuesioner_opsi` AUTO_INCREMENT = 1;

INSERT INTO `kuesioner_kategori` (`id`, `id_status`, `nama`, `deskripsi`, `label_pertanyaan`, `urutan`, `status`, `created_at`, `updated_at`) VALUES
