(2, 6, 'Responden Populasi Kunci', 'Kelompok berisiko tinggi (LSL, WPS, waria, penasun, WBP, dan pasangan berisiko).', 'Variabel Demografi', 2, 1, NOW(), NOW()),
(3, 7, 'Responden ODHIV (Orang Dengan HIV)', 'Orang dengan HIV yang menjalani perawatan/pengobatan, sebagai pengguna utama layanan telefarmasi.', 'Variabel Demografi', 3, 1, NOW(), NOW()),
(4, 8, 'Responden Tenaga Kesehatan', 'Penyedia layanan (dokter, apoteker, TTK, perawat, bidan, dll.) yang mengelola layanan telefarmasi.', 'Variabel Demografi', 4, 1, NOW(), NOW()),
(5, 7, 'Medication Adherence Rating Scale (MARS-5)', 'Di bawah ini terdapat beberapa pernyataan. Pilih satu jawaban yang paling sesuai dengan cara Anda menggunakan obat-obatan. Tidak ada jawaban yang salah atau benar.', 'Pernyataan', 4, 1, NOW(), NOW());

